use xiom.io;

type Movie = {
  title: Str;
  year: Int;
  rating: Float64;
}

enum Genre { Action, Comedy, Drama, Horror, SciFi }

enum OrderStatus { Preparing, OnTheWay, Delivered, Cancelled }

type Order = {
  food: Str;
  price: Float64;
  status: OrderStatus;
}

enum Note { C, D, E, F, G, A, B }

type Chord = {
  root: Note;
  quality: Str;
}

fn Movie.is_classic(self) -> Bool {
  return year < 2000 && rating > 8.0;
}

fn OrderStatus.is_active(self) -> Bool {
  match self {
    Preparing => { return true; }
    OnTheWay => { return true; }
    Delivered => { return false; }
    Cancelled => { return false; }
  }
}

fn Chord.name(self) -> Str {
  return note_name(root) + " " + quality;
}

fn note_name(n: Note) -> Str {
  match n {
    C => { return "C"; }
    D => { return "D"; }
    E => { return "E"; }
    F => { return "F"; }
    G => { return "G"; }
    A => { return "A"; }
    B => { return "B"; }
  }
}

fn main() -> Int {
  let m = Movie{ title: "The Matrix"; year: 1999; rating: 8.7; };
  let o = Order{ food: "Pizza"; price: 12.99; status: OrderStatus.Preparing; };
  let c = Chord{ root: Note.C; quality: "major"; };
  return 3;
}
